import { describe, expect, test } from "bun:test";
import { OPENUI_JSON_PARITY_FIXTURE } from "@keating/learner-contracts";
import { extractUiDocuments, hideUnclosedUiDocumentFence, scopeUiDocument } from "../src/lib/ui-document-wire";

const DOCUMENT = {
  schemaVersion: 1,
  id: "check-1",
  revision: 0,
  lifecycle: "ready",
  supportedSurfaces: ["mobile", "web"],
  nodes: [{ type: "question", id: "question-1", prompt: "What changes the posterior?" }],
  createdAt: "2026-08-10T00:00:00.000Z",
  updatedAt: "2026-08-10T00:00:00.000Z",
};

describe("mobile OpenUI document wire", () => {
  test("extracts validated JSON documents without displaying their source", () => {
    const parsed = extractUiDocuments(`Before\n\n\`\`\`openui\n${JSON.stringify(DOCUMENT)}\n\`\`\`\n\nAfter`);
    expect(parsed.content).toBe("Before\n\n\nAfter");
    expect(parsed.documents).toEqual([DOCUMENT]);
    expect(parsed.errors).toEqual([]);
  });

  test("fails closed for browser programs, unsafe documents, and non-mobile surfaces", () => {
    const browserProgram = extractUiDocuments("```openui\nroot = Question([])\n```");
    expect(browserProgram.documents).toEqual([]);
    expect(browserProgram.errors[0]).toContain("could not be rendered");
    const webOnly = extractUiDocuments(`\`\`\`keating-ui\n${JSON.stringify({ ...DOCUMENT, supportedSurfaces: ["web"] })}\n\`\`\``);
    expect(webOnly.documents).toEqual([]);
    expect(webOnly.errors[0]).toContain("does not declare mobile support");
  });

  test("hides only an unfinished interactive fence while streaming", () => {
    expect(hideUnclosedUiDocumentFence("Visible\n```keating-ui\n{\"schemaVersion\":" )).toBe("Visible");
    const complete = `Visible\n\`\`\`keating-ui\n${JSON.stringify(DOCUMENT)}\n\`\`\``;
    expect(hideUnclosedUiDocumentFence(complete)).toBe(complete);
  });

  test("namespaces model-authored document ids to their persisted event", () => {
    const first = scopeUiDocument(DOCUMENT as never, "session-1:message-1:0");
    const replay = scopeUiDocument(DOCUMENT as never, "session-1:message-1:0");
    const otherSession = scopeUiDocument(DOCUMENT as never, "session-2:message-1:0");
    expect(first.id).toBe(replay.id);
    expect(first.id).not.toBe(otherSession.id);
    expect(first.id).toStartWith(`${DOCUMENT.id}--`);
    expect(DOCUMENT.id).toBe("check-1");
  });

  test("extracts the versioned canonical OpenUI fixture without leaking its wire source", () => {
    const parsed = extractUiDocuments(`Before\n\n\`\`\`openui\n${JSON.stringify(OPENUI_JSON_PARITY_FIXTURE)}\n\`\`\`\n\nAfter`);
    expect(parsed.errors).toEqual([]);
    expect(parsed.documents).toHaveLength(1);
    expect(parsed.documents[0]?.nodes.map((node) => node.type)).toEqual(OPENUI_JSON_PARITY_FIXTURE.nodes.map((node) => node.type));
    expect(parsed.content).toBe("Before\n\n\nAfter");
  });

  test("extracts aggregate question, quiz, and deck nodes as one scoped mobile document", () => {
