          type: "quiz",
          id: "quiz",
          title: "Check",
          questions: [{ id: "q1", kind: "choice", prompt: "What updates a prior?", choices: [{ id: "data", label: "Data" }] }],
        },
        {
          type: "deck",
          id: "deck",
          title: "Bayes cards",
          topic: "Bayesian inference",
          cards: [{ id: "card", front: "Prior", back: "Belief before evidence", tags: [] }],
        },
      ],
    };
    const parsed = extractUiDocuments(`\`\`\`keating-ui\n${JSON.stringify(aggregateDocument)}\n\`\`\``);
    expect(parsed.errors).toEqual([]);
    expect(parsed.documents).toHaveLength(1);
    expect(parsed.documents[0]?.nodes.map((node) => node.type)).toEqual(["question-group", "quiz", "deck"]);
