function validRevision(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function boundedString(value: unknown, maxLength = MAX_TEXT, allowEmpty = false): value is string {
  return typeof value === "string" && value.length <= maxLength && (allowEmpty || value.trim().length > 0);
}

function boundedArray(value: unknown, maxLength: number): value is unknown[] {
  return Array.isArray(value) && value.length <= maxLength;
}

function uniqueIds(entries: ReadonlyArray<{ id: string }>): boolean {
  return new Set(entries.map((entry) => entry.id)).size === entries.length;
}

function validateUiOption(value: unknown): value is UiOption {
  return hasOnlyKeys(value, OPTION_KEYS) && isContractId((value as UiOption).id) && boundedString((value as UiOption).label, 512);
}

function validateUiRowAnswer(value: unknown): value is UiRowAnswer {
  if (!hasOnlyKeys(value, ROW_ANSWER_KEYS)) return false;
  const answer = value as UiRowAnswer;
  return boundedString(answer.item, 2048) && isContractId(answer.optionId)
    && (answer.reason === undefined || boundedString(answer.reason, 8192, true));
}

function validateQuestionFields(value: Record<string, unknown>): boolean {
  const choices = value.choices;
  const items = value.items;
  const blanks = value.blanks;
  const questionType = value.kind;
  const allowedTypes = new Set<UiQuestionType>(["choice", "text", "blanks", "classification", "matching", "multiple_choice", "multi_select", "true_false", "fill_in", "short_answer", "transfer", "slider", "dropdown"]);
  const allowedLevels = new Set<UiQuestionLevel>(["recall", "comprehension", "application", "analysis", "transfer"]);
  if (!boundedString(value.prompt, 4096)) return false;
  if (choices !== undefined && !(boundedArray(choices, MAX_CHOICES) && choices.length > 0 && choices.every(validateUiOption) && uniqueIds(choices))) return false;
  if (questionType !== undefined && !allowedTypes.has(questionType as UiQuestionType)) return false;
  if (value.level !== undefined && !allowedLevels.has(value.level as UiQuestionLevel)) return false;
  for (const key of ["header", "hint", "itemLabel", "choiceLabel", "reasonLabel", "correctAnswer", "explanation", "rubric"] as const) {
    if (value[key] !== undefined && !boundedString(value[key], key === "explanation" || key === "rubric" ? 8192 : 4096, true)) return false;
  }
  for (const key of ["allowText", "multiSelect", "requireReasons", "uniqueMatches"] as const) {
    if (value[key] !== undefined && typeof value[key] !== "boolean") return false;
  }
  if (items !== undefined && !(boundedArray(items, MAX_CHOICES) && items.length > 0 && items.every((item) => boundedString(item, 2048)))) return false;
  if (blanks !== undefined && !(boundedArray(blanks, MAX_CHOICES) && blanks.every((blank) => {
    if (!hasOnlyKeys(blank, new Set(["placeholder", "hint"]))) return false;
    const candidate = blank as { placeholder?: unknown; hint?: unknown };
    return (candidate.placeholder === undefined || boundedString(candidate.placeholder, 512, true))
      && (candidate.hint === undefined || boundedString(candidate.hint, 1024, true));
  }))) return false;
  for (const key of ["correctMatches", "correctAnswers"] as const) {
    const entries = value[key];
    if (entries !== undefined && !(boundedArray(entries, MAX_CHOICES) && entries.every((entry) => boundedString(entry, 4096, true)))) return false;
  }
  if (value.timeLimit !== undefined && !(typeof value.timeLimit === "number" && Number.isSafeInteger(value.timeLimit) && value.timeLimit > 0)) return false;
  for (const key of ["min", "max", "step"] as const) if (value[key] !== undefined && !(typeof value[key] === "number" && Number.isFinite(value[key]))) return false;
  if (typeof value.min === "number" && typeof value.max === "number" && value.min >= value.max) return false;
  if (typeof value.step === "number" && value.step <= 0) return false;
  if (value.multiSelect === true && choices === undefined) return false;
  if ((questionType === "classification" || questionType === "matching") && (items === undefined || choices === undefined)) return false;
  if ((questionType === "choice" || questionType === "multiple_choice" || questionType === "multi_select" || questionType === "dropdown") && choices === undefined && value.allowText !== true) return false;
  if (questionType === "matching" && Array.isArray(value.correctMatches) && value.correctMatches.length !== (items as unknown[]).length) return false;
	if (questionType === "matching" && Array.isArray(value.correctMatches)) {
		const optionIds = new Set((choices as UiOption[]).map((choice) => choice.id));
		if (!value.correctMatches.every((optionId) => typeof optionId === "string" && optionIds.has(optionId))) return false;
	}
  return true;
}

function validateUiQuestion(value: unknown): value is UiQuestion {
  return hasOnlyKeys(value, NESTED_QUESTION_KEYS)
    && isContractId((value as UiQuestion).id)
    && validateQuestionFields(value as Record<string, unknown>);
}

function validateQuestionGroupNode(value: Record<string, unknown>): boolean {
  return hasOnlyKeys(value, QUESTION_GROUP_KEYS)
    && (value.title === undefined || boundedString(value.title, 512, true))
    && (value.intro === undefined || boundedString(value.intro, 8192, true))
    && (value.topic === undefined || boundedString(value.topic, 512, true))
    && boundedArray(value.questions, MAX_QUIZ_QUESTIONS) && value.questions.length > 0
    && value.questions.every(validateUiQuestion) && uniqueIds(value.questions as UiQuestion[]);
}

function validateStudyPlanItem(value: unknown, depth: number, seen: Set<string>): value is UiStudyPlanItem {
  if (depth > MAX_PLAN_DEPTH || !hasOnlyKeys(value, PLAN_ITEM_KEYS)) return false;
  const item = value as UiStudyPlanItem;
  if (!isContractId(item.id) || seen.has(item.id) || !boundedString(item.title, 512)) return false;
  seen.add(item.id);
  if (item.detail !== undefined && !boundedString(item.detail, 8192, true)) return false;
  if (item.estimatedMinutes !== undefined && !(Number.isSafeInteger(item.estimatedMinutes) && item.estimatedMinutes > 0 && item.estimatedMinutes <= 600)) return false;
  if (item.status !== undefined && item.status !== "not_started" && item.status !== "in_progress" && item.status !== "done") return false;
  if (item.dependsOn !== undefined && !(boundedArray(item.dependsOn, 32) && item.dependsOn.every(isContractId) && new Set(item.dependsOn).size === item.dependsOn.length)) return false;
  if (item.outcomes !== undefined && !(boundedArray(item.outcomes, 32) && item.outcomes.every((outcome) => boundedString(outcome, 2048)))) return false;
  return item.children === undefined || (boundedArray(item.children, 20) && item.children.length > 0 && item.children.every((child) => validateStudyPlanItem(child, depth + 1, seen)));
}

function validateStudyPlanNode(value: Record<string, unknown>): boolean {
  if (!hasOnlyKeys(value, STUDY_PLAN_KEYS)) return false;
  const resourceValid = value.resource !== undefined && validateArtifactResource(value.resource);
  if (value.items === undefined) return resourceValid;
  if (!boundedString(value.title, 512) || !boundedArray(value.items, 12) || value.items.length === 0) return false;
  const seen = new Set<string>();
  if (!value.items.every((item) => validateStudyPlanItem(item, 0, seen)) || seen.size > MAX_PLAN_ITEMS) return false;
  const flatItems = flattenPlanItems(value.items as UiStudyPlanItem[]);
  if (!planDependenciesAreValid(flatItems)) return false;
  if (value.overview !== undefined && !boundedString(value.overview, 8192, true)) return false;
  if (value.relatedPlans !== undefined && !(boundedArray(value.relatedPlans, 16) && value.relatedPlans.every((link) => {
    if (!hasOnlyKeys(link, PLAN_LINK_KEYS)) return false;
    const candidate = link as UiStudyPlanLink;
    return isContractId(candidate.planId) && boundedString(candidate.title, 512)
      && (candidate.relation === undefined || candidate.relation === "prerequisite" || candidate.relation === "follow-up" || candidate.relation === "related")
      && (candidate.detail === undefined || boundedString(candidate.detail, 4096, true));
  }) && new Set((value.relatedPlans as UiStudyPlanLink[]).map((link) => link.planId)).size === value.relatedPlans.length)) return false;
  return value.resource === undefined || resourceValid;
}

function flattenPlanItems(items: readonly UiStudyPlanItem[]): UiStudyPlanItem[] {
  return items.flatMap((item) => [item, ...(item.children ? flattenPlanItems(item.children) : [])]);
}

function planDependenciesAreValid(items: readonly UiStudyPlanItem[]): boolean {
  const byId = new Map(items.map((item) => [item.id, item]));
  if (items.some((item) => item.dependsOn?.some((id) => id === item.id || !byId.has(id)))) return false;
  const visiting = new Set<string>();
  const visited = new Set<string>();
  const visit = (id: string): boolean => {
    if (visiting.has(id)) return false;
    if (visited.has(id)) return true;
    visiting.add(id);
    for (const dependency of byId.get(id)?.dependsOn ?? []) if (!visit(dependency)) return false;
    visiting.delete(id);
    visited.add(id);
    return true;
  };
  return items.every((item) => visit(item.id));
}

function validateGoalStep(value: unknown): value is UiGoalStep {
  const step = value as UiGoalStep;
  return hasOnlyKeys(value, GOAL_STEP_KEYS) && isContractId(step.id) && boundedString(step.title, 512)
    && GOAL_STEP_STATUSES.has(step.status)
    && (step.successCriteria === undefined || (boundedArray(step.successCriteria, MAX_CHOICES) && step.successCriteria.every((criterion) => boundedString(criterion, 1024))));
}

function validateDeckCard(value: unknown): value is UiDeckCard {
  const card = value as UiDeckCard;
  return hasOnlyKeys(value, CARD_KEYS) && isContractId(card.id) && boundedString(card.front, 4096) && boundedString(card.back, 8192)
    && (card.tags === undefined || (boundedArray(card.tags, MAX_TAGS) && card.tags.every((tag) => boundedString(tag, 256))));
}

function isSafeResourceUri(value: unknown): value is string {
  if (!boundedString(value, 4096)) return false;
  try {
    const url = new URL(value);
    if (url.username || url.password || url.search || url.hash) return false;
    if (url.protocol === "https:") return !!url.hostname;
    if (url.protocol === "artifact:") return isContractId(url.hostname || url.pathname.replace(/^\/+/, ""));
    return url.protocol === "http:" && (url.hostname === "127.0.0.1" || url.hostname === "localhost" || url.hostname === "[::1]");
  } catch {
    return false;
  }
}

function validateArtifactResource(value: unknown, requireUri = false): value is UiArtifactResource {
  const resource = value as UiArtifactResource;
  if (!hasOnlyKeys(value, RESOURCE_KEYS) || !isContractId(resource.id) || !boundedString(resource.title, 512)
    || !ARTIFACT_FORMATS.has(resource.format) || (resource.content !== undefined && !boundedString(resource.content, MAX_RESOURCE_CONTENT, true))
    || (resource.uri !== undefined && !isSafeResourceUri(resource.uri))
    || (resource.mimeType !== undefined && !boundedString(resource.mimeType, 256))) return false;
  if (resource.format === "uri" && resource.uri === undefined) return false;
  return requireUri ? resource.uri !== undefined : resource.content !== undefined || resource.uri !== undefined;
}

function validateUiDocumentNode(value: unknown): value is UiDocumentNode {
  if (!isRecord(value) || !isContractId(value.id) || typeof value.type !== "string") return false;
  switch (value.type) {
    case "markdown": return hasOnlyKeys(value, MARKDOWN_KEYS) && boundedString(value.markdown, MAX_MARKDOWN, true);
    case "callout": return hasOnlyKeys(value, CALLOUT_KEYS) && boundedString(value.markdown, MAX_MARKDOWN, true)
      && (value.tone === "info" || value.tone === "hint" || value.tone === "check" || value.tone === "warning")
      && (value.title === undefined || boundedString(value.title, 512, true));
    case "question": return hasOnlyKeys(value, QUESTION_KEYS) && validateQuestionFields(value);
    case "question-group": return validateQuestionGroupNode(value);
    case "quiz": return hasOnlyKeys(value, QUIZ_KEYS) && boundedString(value.title, 512)
      && boundedArray(value.questions, MAX_QUIZ_QUESTIONS) && value.questions.every(validateUiQuestion) && uniqueIds(value.questions);
    case "goal": return hasOnlyKeys(value, GOAL_KEYS) && boundedString(value.title, 512)
      && (value.description === undefined || boundedString(value.description, 4096, true))
      && (value.status === "active" || value.status === "completed" || value.status === "paused")
      && boundedArray(value.steps, MAX_GOAL_STEPS) && value.steps.every(validateGoalStep) && uniqueIds(value.steps);
    case "deck": return hasOnlyKeys(value, DECK_KEYS) && boundedString(value.title, 512) && boundedString(value.topic, 512)
      && (value.description === undefined || boundedString(value.description, 8192, t…9846 tokens truncated…ew>;
}

function DeckNode({ node, document, disabled, busy, durableActions, run }: NodeActionProps<Extract<UiDocumentNode, { type: "deck" }>> & { durableActions: readonly UiAction[] }) {
  const styles = createStyles(useKeatingTheme());
  const completedAction = completedDeckAction(durableActions, node.id);
  const hasLegacyRatings = durableActions.some((action) => action.type === "rate-card" && action.nodeId === node.id);
  if (completedAction) return <View style={styles.node}>
    <Text style={styles.nodeKicker}>FLASHCARDS</Text>
    <Text style={styles.nodeTitle}>{node.title}</Text>
    <Text accessibilityLiveRegion="polite" style={styles.savedAnswer}>Deck review complete. {completedAction.summary.reviewed} card{completedAction.summary.reviewed === 1 ? "" : "s"} reviewed.</Text>
  </View>;
  if (hasLegacyRatings) return <LegacyDeckNode node={node} document={document} disabled={disabled} busy={busy} durableActions={durableActions} run={run} />;
  return <AggregateDeckNode node={node} document={document} disabled={disabled} busy={busy} durableActions={durableActions} run={run} />;
}

function AggregateDeckNode({ node, document, disabled, busy, durableActions, run }: NodeActionProps<Extract<UiDocumentNode, { type: "deck" }>> & { durableActions: readonly UiAction[] }) {
  const styles = createStyles(useKeatingTheme());
  const [revealed, setRevealed] = useState(false);
  const savedAction = completedDeckAction(durableActions, node.id);
  const [ratings, setRatings] = useState<Extract<UiAction, { type: "complete-deck" }>['ratings']>(() => savedAction?.ratings ?? []);
  const [pendingAction, setPendingAction] = useState<Extract<UiAction, { type: "complete-deck" }>>();
  const [delivered, setDelivered] = useState(false);
  useEffect(() => {
    if (savedAction) setRatings(savedAction.ratings);
  }, [savedAction]);
  const index = ratings.length;
  const completed = Boolean(savedAction) || delivered;
  if (completed || (node.cards.length > 0 && index >= node.cards.length)) return <View style={styles.node}>
    <Text style={styles.nodeKicker}>FLASHCARDS</Text>
    <Text style={styles.nodeTitle}>{node.title}</Text>
    <Text accessibilityLiveRegion="polite" style={styles.savedAnswer}>Deck review complete. {ratings.length} card{ratings.length === 1 ? "" : "s"} reviewed.</Text>
  </View>;
  const card = node.cards[index];
  if (!card) return <Text style={styles.body}>This deck has no cards.</Text>;
  const complete = async (nextRatings: typeof ratings) => {
    const summary = { reviewed: nextRatings.length, lapses: nextRatings.filter((entry) => entry.rating === 0).length };
    const action = pendingAction ?? buildDeckCompletionAction(document, node.id, { ratings: nextRatings, summary });
    if (!pendingAction) setPendingAction(action);
    if (await run(action, false)) {
      setPendingAction(undefined);
      setDelivered(true);
    }
  };
  const rate = (rating: 0 | 1 | 2 | 3) => {
    const outcome = applyReview(initialSrsState(document.updatedAt), rating, document.updatedAt);
    const nextRatings = [...ratings, { cardId: card.id, rating, appliedIntervalDays: outcome.appliedIntervalDays, easeAfter: outcome.next.ease }];
    setRatings(nextRatings);
    setRevealed(false);
    if (index + 1 === node.cards.length) void complete(nextRatings);
  };
  return <View style={styles.node}>
    <Text style={styles.nodeKicker}>FLASHCARDS · {index + 1}/{node.cards.length}</Text>
    <Text style={styles.nodeTitle}>{node.title}</Text>
    <Pressable accessibilityRole="button" accessibilityState={{ disabled: disabled || Boolean(pendingAction) }} accessibilityLabel={revealed ? "Hide card answer" : "Reveal card answer"} disabled={disabled || Boolean(pendingAction)} onPress={() => setRevealed((current) => !current)} style={({ pressed }) => [styles.flashcard, pressed && styles.pressed]}>
      <Text style={styles.cardFace}>{card.front}</Text>
      {revealed ? <Text style={styles.cardBack}>{card.back}</Text> : <Text style={styles.revealHint}>Tap to reveal</Text>}
    </Pressable>
    {pendingAction ? <View style={styles.options}><Text accessibilityLiveRegion="polite" style={styles.savedAnswer}>Final rating is ready to retry.</Text><Button compact disabled={disabled} loading={busy === pendingAction.idempotencyKey} onPress={() => void complete(pendingAction.ratings)}>Retry save deck</Button></View> : revealed ? <View style={styles.ratingRow}>{([0, 1, 2, 3] as const).map((rating) => {
      const labels = ["Again", "Hard", "Good", "Easy"] as const;
      return <Button key={rating} compact variant="secondary" disabled={disabled} style={styles.ratingButton} onPress={() => rate(rating)}>{labels[rating]}</Button>;
    })}</View> : null}
  </View>;
}

function LegacyDeckNode({ node, document, disabled, busy, durableActions, run }: NodeActionProps<Extract<UiDocumentNode, { type: "deck" }>> & { durableActions: readonly UiAction[] }) {
  const styles = createStyles(useKeatingTheme());
  const [revealed, setRevealed] = useState(false);
  const reviewed = reviewedDeckCardIds(durableActions, node.id);
  const index = node.cards.findIndex((candidate) => !reviewed.has(candidate.id));
  if (node.cards.length > 0 && index < 0) return <View style={styles.node}>
    <Text style={styles.nodeKicker}>FLASHCARDS</Text>
    <Text style={styles.nodeTitle}>{node.title}</Text>
    <Text accessibilityLiveRegion="polite" style={styles.savedAnswer}>Deck review complete. The card schedules were saved to Review.</Text>
  </View>;
  const card = node.cards[index];
  if (!card) return <Text style={styles.body}>This deck has no cards.</Text>;
  return <View style={styles.node}>
    <Text style={styles.nodeKicker}>FLASHCARDS · {index + 1}/{node.cards.length}</Text>
    <Text style={styles.nodeTitle}>{node.title}</Text>
    <Pressable accessibilityRole="button" accessibilityLabel={revealed ? "Hide card answer" : "Reveal card answer"} onPress={() => setRevealed((current) => !current)} style={({ pressed }) => [styles.flashcard, pressed && styles.pressed]}>
      <Text style={styles.cardFace}>{card.front}</Text>
      {revealed ? <Text style={styles.cardBack}>{card.back}</Text> : <Text style={styles.revealHint}>Tap to reveal</Text>}
    </Pressable>
    {revealed ? <View style={styles.ratingRow}>{([0, 1, 2, 3] as const).map((rating) => {
      const labels = ["Again", "Hard", "Good", "Easy"] as const;
      const key = actionKey(document, "rate-card", node.id, `${card.id}:${rating}`);
      const action: UiAction = { schemaVersion: UI_CONTRACT_VERSION, type: "rate-card", documentId: document.id, documentRevision: document.revision, nodeId: node.id, cardId: card.id, rating, idempotencyKey: key };
      return <Button key={rating} compact variant="secondary" disabled={disabled} loading={busy === key} style={styles.ratingButton} onPress={() => void run(action, false).then((saved) => { if (saved) setRevealed(false); })}>{labels[rating]}</Button>;
    })}</View> : null}
  </View>;
}

type ResourceNodeType = Extract<UiDocumentNode, { type: "artifact" | "image" | "media" }>;

function ResourceNode({ node, document, disabled, busy, durableActions, run }: NodeActionProps<ResourceNodeType> & { durableActions: readonly UiAction[] }) {
  const styles = createStyles(useKeatingTheme());
  const resource = node.resource;
  const saved = completedNodeAction(durableActions, node.id, "save-artifact");
  const key = actionKey(document, "save-artifact", node.id, resource.id);
  const action: UiAction = { schemaVersion: 1, type: "save-artifact", documentId: document.id, documentRevision: document.revision, nodeId: node.id, idempotencyKey: key };
  return <View style={styles.node}>
    <Text style={styles.nodeKicker}>{node.type.replace("-", " ").toUpperCase()}</Text>
    <Text style={styles.nodeTitle}>{resource.title}</Text>
    {node.type === "image" && resource.uri ? <ConsentImage uri={resource.uri} alt={node.alt} /> : null}
    {node.type === "media" && node.kind === "audio" && resource.uri ? <ConsentAudio uri={resource.uri} title={resource.title} /> : null}
    {resource.content ? resource.format === "markdown" ? <MarkdownText content={resource.content} /> : <ScrollView horizontal><Text selectable style={styles.code}>{resource.content}</Text></ScrollView> : null}
    {resource.uri && node.type !== "image" && !(node.type === "media" && node.kind === "audio") && safeMarkdownUri(resource.uri, "link")
      ? <Button variant="secondary" compact onPress={() => confirmOpenResource(resource.title, resource.uri!)}>Open {node.type === "media" ? node.kind : "resource"}</Button>
      : null}
    {resource.uri?.startsWith("artifact:") ? <Text style={styles.body}>This artifact reference can be saved to your local library.</Text> : null}
    <Button compact disabled={disabled || saved} loading={busy === key} onPress={() => void run(action, false)}>{saved ? "Saved to library" : "Save to library"}</Button>
  </View>;
}

function LegacyStudyPlanResourceNode({ node, document, disabled, busy, durableActions, run }: NodeActionProps<Extract<UiDocumentNode, { type: "study-plan" }>> & { durableActions: readonly UiAction[] }) {
  const styles = createStyles(useKeatingTheme());
  const resource = node.resource;
  if (!resource) return null;
  const saved = completedNodeAction(durableActions, node.id, "save-artifact");
  const key = actionKey(document, "save-artifact", node.id, resource.id);
  const action: UiAction = { schemaVersion: UI_CONTRACT_VERSION, type: "save-artifact", documentId: document.id, documentRevision: document.revision, nodeId: node.id, idempotencyKey: key };
  return <View style={styles.node}>
    <Text style={styles.nodeKicker}>STUDY PLAN</Text>
    <Text style={styles.nodeTitle}>{resource.title}</Text>
    {resource.content ? resource.format === "markdown" ? <MarkdownText content={resource.content} /> : <ScrollView horizontal><Text selectable style={styles.code}>{resource.content}</Text></ScrollView> : null}
    <Button compact disabled={disabled || saved} loading={busy === key} onPress={() => void run(action, false)}>{saved ? "Saved to library" : "Save to library"}</Button>
  </View>;
}

function HandoffNode({ node, document, disabled, busy, run }: NodeActionProps<Extract<UiDocumentNode, { type: "handoff" }>>) {
  const styles = createStyles(useKeatingTheme());
  const key = actionKey(document, "open-handoff", node.id, node.target);
  const action: UiAction = { schemaVersion: 1, type: "open-handoff", documentId: document.id, documentRevision: document.revision, nodeId: node.id, idempotencyKey: key };
  return <View style={styles.node}><Text style={styles.nodeKicker}>CONTINUE ON {node.target.toUpperCase()}</Text><Text style={styles.nodeTitle}>{node.reason}</Text><Text style={styles.body}>{node.context}</Text><Button disabled={disabled} loading={busy === key} onPress={() => void run(action, false).then((saved) => { if (saved) openHandoff(node.target); })}>Open handoff</Button></View>;
}

interface NodeActionProps<T extends UiDocumentNode> {
  node: T;
  document: UiDocument;
  disabled: boolean;
  busy: string | null;
  run: (action: UiAction, learnerTurn?: boolean) => Promise<boolean>;
}

function ConsentImage({ uri, alt }: { uri: string; alt: string }) {
  const styles = createStyles(useKeatingTheme());
  const [allowed, setAllowed] = useState(false);
  const safe = useMemo(() => safeMarkdownUri(uri, "image"), [uri]);
  if (!safe) return <Text style={styles.error}>Blocked unsafe image.</Text>;
  return allowed
    ? <Image accessibilityLabel={alt} accessibilityIgnoresInvertColors source={{ uri: safe.toString() }} resizeMode="contain" style={styles.image} />
    : <Button variant="secondary" compact onPress={() => setAllowed(true)}>Load image</Button>;
}

function ConsentAudio({ uri, title }: { uri: string; title: string }) {
  const styles = createStyles(useKeatingTheme());
  const [allowed, setAllowed] = useState(false);
  const safe = useMemo(() => safeMarkdownUri(uri, "image"), [uri]);
  if (!safe) return <Text style={styles.error}>Blocked unsafe audio source.</Text>;
  return allowed
    ? <NativeAudioPlayer uri={safe.toString()} title={title} />
    : <Button variant="secondary" compact onPress={() => setAllowed(true)}>Load audio</Button>;
}

function NativeAudioPlayer({ uri, title }: { uri: string; title: string }) {
  const styles = createStyles(useKeatingTheme());
  const player = useAudioPlayer({ uri, name: title });
  const status = useAudioPlayerStatus(player);
  const duration = status.duration > 0 ? `${formatTime(status.currentTime)} / ${formatTime(status.duration)}` : "Loading audio…";
  return <View style={styles.audioPlayer}>
    <Button
      compact
      variant="secondary"
      disabled={!status.isLoaded || !!status.error}
      onPress={() => status.playing ? player.pause() : player.play()}
    >{status.playing ? "Pause" : "Play"}</Button>
    <Text accessibilityLiveRegion="polite" style={styles.audioStatus}>{status.error ?? duration}</Text>
  </View>;
}

function formatTime(seconds: number): string {
  const safe = Number.isFinite(seconds) && seconds > 0 ? Math.floor(seconds) : 0;
  return `${Math.floor(safe / 60)}:${String(safe % 60).padStart(2, "0")}`;
}

function completedAnswerLabel(
  action: Extract<UiAction, { type: "submit-answer" | "choose-option" }>,
  question: UiQuestion,
): string {
  if (action.type === "submit-answer") {
    if (typeof action.answer === "string") return action.answer;
    if (action.answer.every((entry) => typeof entry === "string")) return action.answer.join(", ");
    const labels = new Map(question.choices?.map((choice) => [choice.id, choice.label]) ?? []);
    return action.answer.map((row) => `${row.item}: ${labels.get(row.optionId) ?? row.optionId}${row.reason ? ` — ${row.reason}` : ""}`).join(", ");
  }
  const labels = new Map(question.choices?.map((choice) => [choice.id, choice.label]) ?? []);
  return action.optionIds.map((id) => labels.get(id) ?? id).join(", ");
}

function confirmOpenResource(label: string, uri: string): void {
  const safe = safeMarkdownUri(uri, "link");
  if (!safe) return;
  Alert.alert("Open external resource?", `${label}\n${safe.hostname}`, [
    { text: "Cancel", style: "cancel" },
    { text: "Open", onPress: () => void Linking.openURL(safe.toString()) },
  ]);
}

function openHandoff(target: string): void {
  if (target !== "web") {
    Alert.alert("Handoff saved", `Continue this interaction in Keating ${target}.`);
    return;
  }
  Alert.alert("Open Keating on the web?", "The interaction context remains saved on this device.", [
    { text: "Cancel", style: "cancel" },
    { text: "Open web", onPress: () => void Linking.openURL("https://keating.help") },
  ]);
}

function createStyles(theme: ReturnType<typeof useKeatingTheme>) {
